def consecutive_groups(values):
    import itertools
    return [list(g) for _,g in itertools.groupby(values)]

def weighted_mean(values, weights):
    if len(values)!=len(weights) or sum(weights)==0: raise ValueError
    return sum(v*w for v,w in zip(values,weights))/sum(weights)

def drop_every(values, n):
    if n<=0: raise ValueError
    return [v for i,v in enumerate(values,1) if i%n]

def longest_word(text):
    words=text.split()
    return max(words,key=len) if words else None

def snake_to_camel(text):
    parts=[p for p in text.split("_") if p]
    return parts[0]+"".join(p[:1].upper()+p[1:] for p in parts[1:]) if parts else ""

def mask_tail(text, keep):
    keep=max(0,keep)
    return "*"*max(0,len(text)-keep)+(text[-keep:] if keep else "")

def find_duplicate_keys(pairs):
    seen=set(); result=[]
    for key,_ in pairs:
     if key in seen and key not in result: result.append(key)
     seen.add(key)
    return result

