from pathlib import Path
from html.parser import HTMLParser
import re
s=Path('index.html').read_text(encoding='utf-8')
class P(HTMLParser):
 def __init__(self): super().__init__(); self.ids=[];self.text=[]
 def handle_starttag(self,t,a):
  d=dict(a)
  if 'id' in d:self.ids.append(d['id'])
 def handle_data(self,d):self.text.append(d)
p=P();p.feed(s)
assert p.ids==['panel','badge']
for text in ['Upload progress', '68% complete', '68%']: assert text in ''.join(p.text)
compact=re.sub(r'\s+','',s.lower())
for expected in ['width:480px', 'padding:24px', 'border-left:8px solid #176b87', 'background:#176b87', 'color:white', 'border-radius:8px']:assert re.sub(r'\s+','',expected) in compact

